CREATE TABLE `detalles_ventas_pagos` (
  `col_1` VARCHAR(20)
);

CREATE TABLE `detalles_ventas` (
  `id` BIGINT NOT NULL,
  `id_salida` BIGINT,
  `medida` VARCHAR(14),
  `marca` VARCHAR(15),
  `modelo` VARCHAR(30),
  `stock_si_no` TINYINT(1),
  `cantidad_llantas_vendidas` DECIMAL(38,10),
  `orden_de_compra` VARCHAR(8),
  `proveedor` VARCHAR(21),
  `numero_de_factura` VARCHAR(17),
  `fecha_de_compra` DATETIME,
  `fecha_de_venta` DECIMAL(38,10),
  `p_venta` DECIMAL(38,10),
  `p_compra` DECIMAL(38,10),
  `detalle_facturas_usadas` VARCHAR(31),
  `ganancia_calculada` DECIMAL(38,10),
  CONSTRAINT `pk_detalles_ventas` PRIMARY KEY (`id`),
  CONSTRAINT `fk_detalles_ventas_id_salida` FOREIGN KEY (`id_salida`) REFERENCES `salida`(`id`)
);
ALTER TABLE `detalles_ventas` ADD INDEX `ix_detalles_ventas_id_salida` (`id_salida`);

CREATE TABLE `salidas` (
  `id_sal` BIGINT,
  `cod_prod` VARCHAR(20) NOT NULL,
  `medida` VARCHAR(14),
  `marca` VARCHAR(15),
  `modelo` VARCHAR(30),
  `cantidad` BIGINT,
  `p_venta` DECIMAL(38,10),
  `f_venta` DATETIME,
  `n_fact` VARCHAR(16),
  `proveedor` VARCHAR(21),
  CONSTRAINT `pk_salidas` PRIMARY KEY (`cod_prod`),
  CONSTRAINT `fk_salidas_id_sal` FOREIGN KEY (`id_sal`) REFERENCES `sal`(`id`)
);
ALTER TABLE `salidas` ADD INDEX `ix_salidas_id_sal` (`id_sal`);

CREATE TABLE `entradas` (
  `cod_prod` VARCHAR(20),
  `medida` VARCHAR(14),
  `marca` VARCHAR(15),
  `modelo` VARCHAR(30),
  `c_carga` BIGINT,
  `vel` VARCHAR(8),
  `cantidad` BIGINT,
  `p_compra` DECIMAL(38,10),
  `f_compra` DATETIME,
  `n_fact` VARCHAR(16),
  `proveedor` VARCHAR(21),
  `inventario` VARCHAR(12)
);

CREATE TABLE `inventario` (
  `cod_prod` VARCHAR(20),
  `medidas` VARCHAR(13) NOT NULL,
  `marca` VARCHAR(13),
  `modelo` VARCHAR(18),
  `entrada` BIGINT,
  `salidas` BIGINT,
  `stock` BIGINT,
  `precio` BIGINT,
  CONSTRAINT `pk_inventario` PRIMARY KEY (`medidas`)
);

CREATE TABLE `informacion` (
  `concepto` VARCHAR(25),
  `col_3` VARCHAR(8),
  `cantidad` DECIMAL(38,10) NOT NULL,
  CONSTRAINT `pk_informacion` PRIMARY KEY (`cantidad`)
);







